INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','easy','flashcard','What dye is used first in the Gram stain procedure?','["Crystal violet (primary stain)"]','A','Crystal violet is applied first and stains all bacteria purple; iodine is then added as a mordant to fix the dye.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','easy','flashcard','What colour do Gram-positive bacteria appear after Gram staining?','["Purple/violet"]','A','Gram-positive bacteria retain crystal violet because their thick peptidoglycan layer traps the dye after decolorisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','easy','flashcard','What is the counterstain used in the Gram stain and what colour does it impart to Gram-negative bacteria?','["Safranin; Gram-negative bacteria appear pink/red"]','A','After decolorisation, Gram-negative bacteria lose crystal violet and take up the safranin counterstain, appearing pink.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','medium','flashcard','Why do Gram-positive bacteria retain crystal violet during the Gram stain?','["Thick peptidoglycan cell wall (20–80 nm) traps the crystal violet–iodine complex after alcohol decolorisation"]','A','Gram-negative bacteria have a thin peptidoglycan layer and an outer membrane that is disrupted by alcohol, releasing the dye.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','medium','flashcard','What is the role of lipid A in Gram-negative bacteria?','["Lipid A is the toxic component of LPS (endotoxin); it triggers fever, hypotension, and septic shock via TLR4"]','A','LPS (lipopolysaccharide) is embedded in the outer membrane of Gram-negative bacteria; its lipid A moiety is the primary pyrogen and induces macrophage cytokine release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','medium','flashcard','What is teichoic acid and which type of bacteria contains it?','["Teichoic acid is a surface antigen found in Gram-positive bacterial cell walls; it contributes to adherence and antigenicity"]','A','Lipoteichoic acid anchors to the cytoplasmic membrane and activates the immune system; it is unique to Gram-positive organisms.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','medium','flashcard','What enzyme is the target of beta-lactam antibiotics and what is its normal function?','["Transpeptidase (Penicillin-Binding Protein, PBP); normally cross-links peptidoglycan strands to build the bacterial cell wall"]','A','Beta-lactams bind PBPs irreversibly, preventing peptidoglycan cross-linking and causing cell lysis. MRSA uses an altered PBP2A to resist this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','hard','flashcard','What are the two subunits of the bacterial 70S ribosome and which is targeted by aminoglycosides vs macrolides?','["70S = 30S + 50S; aminoglycosides/tetracyclines target 30S; macrolides/chloramphenicol/clindamycin target 50S"]','A','Mnemonic: ''Buy AT 30, CCLE at 50'' — Buy (aminoglycosides), AT (tetracyclines) bind 30S; Chloramphenicol, Clindamycin, Linezolid, Erythromycin bind 50S.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','hard','flashcard','Why is Mycoplasma pneumoniae intrinsically resistant to beta-lactam antibiotics?','["Mycoplasma has no cell wall (no peptidoglycan), so beta-lactams have no target"]','A','Because it lacks a cell wall, Mycoplasma is also not visualised on Gram stain. Treatment requires macrolides, tetracyclines, or fluoroquinolones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Cell Biology','hard','flashcard','Which organisms are acid-fast and what component of their cell wall confers this property?','["Mycobacteria (e.g., M. tuberculosis, M. leprae) and Nocardia; mycolic acids in the cell wall resist decolorisation by acid-alcohol"]','A','The Ziehl-Neelsen stain uses carbol-fuchsin; acid-fast organisms appear red against a blue background. Mnemonic: ''Acid-fast = Mycobacteria + Nocardia (partially)''.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','easy','flashcard','What is the primary function of bacterial pili (fimbriae)?','["Adherence/attachment to host cell surfaces, initiating colonisation and infection"]','A','Type IV pili also mediate twitching motility and DNA uptake. P-fimbriae of uropathogenic E. coli bind P blood group antigens in the urinary tract.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','easy','flashcard','How does a bacterial capsule help the organism evade host defences?','["Inhibits phagocytosis by masking bacterial surface antigens and preventing complement opsonisation"]','A','Encapsulated organisms (S. pneumoniae, H. influenzae, N. meningitidis, E. coli K1, Klebsiella, Salmonella typhi) cause serious infections especially in asplenic patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','easy','flashcard','What staining technique is used to visualise the Cryptococcus neoformans capsule?','["India ink stain — capsule appears as a clear halo around the budding yeast cell"]','A','The Quellung reaction (capsular swelling with specific antiserum) is used for S. pneumoniae. India ink is specific for Cryptococcus in CSF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','medium','flashcard','Which organism is the classic cause of biofilm-associated prosthetic device infections and why?','["Staphylococcus epidermidis; produces a polysaccharide intercellular adhesin (PIA) biofilm on foreign material"]','A','Biofilm protects bacteria from antibiotics and phagocytes. S. aureus also forms biofilms. Treatment often requires device removal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','medium','flashcard','Describe the A-B toxin structure and explain how the B subunit contributes to pathogenicity.','["B (binding) subunit binds host cell receptor; A (active) subunit is internalised and exerts enzymatic toxic effect"]','A','Examples: cholera toxin B binds GM1 ganglioside; diphtheria toxin B binds HB-EGF receptor. The A subunit is the actual poison.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','medium','flashcard','What is the mechanism of cholera toxin?','["B subunit binds GM1 ganglioside → A subunit ADP-ribosylates Gs protein → permanent activation of adenylyl cyclase → ↑↑ cAMP → massive Cl⁻ and water secretion into gut lumen"]','A','Results in ''rice-water'' stools. cAMP is the key second messenger — same pathway as pertussis toxin (but pertussis inhibits Gi).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','medium','flashcard','How do tetanus toxin and botulinum toxin differ in their clinical effects?','["Tetanus toxin → spastic paralysis (blocks inhibitory neurotransmitter release in spinal cord); Botulinum toxin → flaccid paralysis (blocks ACh release at NMJ)"]','A','Both cleave SNARE proteins but at different sites. Tetanus blocks glycine/GABA release from Renshaw cells; botulinum blocks ACh vesicle fusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','hard','flashcard','What is the mechanism by which TSST-1 (toxic shock syndrome toxin) causes systemic disease?','["TSST-1 is a superantigen: it cross-links MHC II on APCs with TCR Vβ regions on T cells, bypassing normal antigen presentation and causing massive non-specific T-cell activation and cytokine storm"]','A','Up to 20% of T cells may be activated simultaneously (vs 0.01% in normal responses), flooding the body with IL-1, IL-2, TNF-α, and IFN-γ.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','hard','flashcard','Name the classic facultative intracellular organisms using a mnemonic.','["''Some Nasty Bugs May Live FacultativeLY'' — Salmonella, Nocardia, Brucella, Mycobacterium, Listeria, Francisella, Yersinia"]','A','Facultative intracellular organisms survive within macrophages by resisting phagolysosome fusion. Cell-mediated immunity (CD8+/CD4+ Th1) is critical for clearance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Bacterial Virulence & Pathogenesis','hard','flashcard','What is opsonisation and which molecules serve as opsonins?','["Opsonisation is coating of a pathogen to enhance phagocytosis; main opsonins are IgG antibodies and complement C3b"]','A','Fc receptors on phagocytes bind IgG; CR1 receptors bind C3b. Patients with IgG deficiency or C3 deficiency are susceptible to encapsulated bacterial infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','easy','flashcard','What is the significance of a positive-sense (positive-strand) RNA virus genome?','["It can act directly as mRNA and be translated immediately by host ribosomes upon cell entry — no RNA-dependent RNA polymerase needed to initiate replication"]','A','Examples: Picornaviruses (Poliovirus, HAV, Rhinovirus), Flaviviruses (HCV, Dengue, Zika), Coronaviruses. Fastest route to protein synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','easy','flashcard','Why must negative-sense RNA viruses package their own RNA-dependent RNA polymerase (RdRp)?','["The genome is complementary to mRNA and cannot be translated directly; RdRp is required to synthesise positive-sense mRNA immediately after cell entry"]','A','Examples: Orthomyxoviruses (Influenza), Paramyxoviruses (Measles, RSV), Rhabdoviruses (Rabies), Bunyaviruses. Mnemonic: ''Negative Never directly translates''.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','easy','flashcard','What enzyme does HIV (a retrovirus) use to convert its RNA genome into DNA?','["Reverse transcriptase (RNA-dependent DNA polymerase)"]','A','The sequence is: RNA → DNA (reverse transcriptase) → double-stranded DNA → integrated into host chromosome (integrase). NRTIs/NNRTIs target reverse transcriptase.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','medium','flashcard','Which DNA viruses replicate in the cytoplasm rather than the nucleus?','["Poxviruses (e.g., Smallpox, Vaccinia) replicate entirely in the cytoplasm; all other DNA viruses replicate in the nucleus"]','A','Mnemonic for DNA viruses: ''HHAPPPy'' — Herpesviruses, Hepadnaviruses, Adenoviruses, Papillomaviruses, Parvoviruses, Poxviruses (cytoplasm).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','medium','flashcard','Why is Parvovirus B19 unique among DNA viruses?','["It is the only ssDNA (single-stranded DNA) human pathogen; all other DNA viruses are double-stranded"]','A','Parvovirus B19 causes fifth disease (slapped-cheek rash) and aplastic crisis in sickle cell disease by infecting erythroid progenitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','medium','flashcard','Distinguish antigenic drift from antigenic shift in influenza.','["Antigenic drift = gradual point mutations in HA/NA genes → seasonal flu; Antigenic shift = reassortment of gene segments between two influenza strains → pandemic flu"]','A','Antigenic shift requires co-infection of one host (e.g., pig) with human and avian influenza strains. Only Influenza A undergoes true antigenic shift.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','medium','flashcard','What is the function of influenza haemagglutinin (HA)?','["HA mediates viral attachment to sialic acid residues on host respiratory epithelial cells"]','A','HA also mediates membrane fusion to release viral contents. Antibodies against HA are the primary correlate of protective immunity to influenza.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','hard','flashcard','What is the function of influenza neuraminidase (NA) and how do oseltamivir and zanamivir exploit this?','["NA cleaves sialic acid to release new virions from infected cells; oseltamivir/zanamivir inhibit NA, trapping virions on the cell surface and preventing spread"]','A','NA inhibitors are most effective when started within 48 hours of symptom onset. Resistance (H275Y mutation in N1) can develop.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','hard','flashcard','Define viral latency and give two examples of viruses that establish latency.','["Latency = viral genome persists in host cell in a non-replicating state without producing infectious virions; reactivation occurs under immunosuppression or stress"]','A','HSV-1/2 are latent in sensory ganglia; VZV in dorsal root/trigeminal ganglia; EBV in B lymphocytes; CMV in mononuclear cells. Latent virus is not cleared by antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Viral Replication & Pathogenesis','hard','flashcard','What is the mechanism of viral oncogenesis?','["Viral oncoproteins inactivate tumour suppressor genes (e.g., HPV E6 degrades p53; HPV E7 inactivates Rb) OR viral genomes carry oncogenes (v-src) OR chronic inflammation promotes mutagenesis"]','A','Oncogenic viruses: HPV (cervical/oropharyngeal), EBV (Burkitt lymphoma, nasopharyngeal carcinoma), HBV/HCV (hepatocellular carcinoma), HTLV-1 (adult T-cell leukaemia), HHV-8 (Kaposi sarcoma).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','easy','flashcard','What is the dimorphism rule for pathogenic fungi?','["Mould (hyphae) at 25°C (environmental temperature); Yeast at 37°C (body temperature) — ''Mould in cold, Yeast in heat''"]','A','Dimorphic fungi: Histoplasma, Blastomyces, Coccidioides, Paracoccidioides, Sporothrix, Penicillium marneffei. Aspergillus is NOT dimorphic (remains mould in tissue).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','easy','flashcard','Where is ergosterol located in fungi and why is it an antifungal drug target?','["Ergosterol is in the fungal cell membrane (analogous to cholesterol in mammalian membranes); it is absent in human cells, making it a selective antifungal target"]','A','Amphotericin B binds ergosterol directly; azoles inhibit ergosterol synthesis. Selectivity for ergosterol over cholesterol underpins antifungal activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','easy','flashcard','What is the target of echinocandin antifungals (e.g., caspofungin)?','["Beta-(1,3)-glucan synthase in the fungal cell wall; inhibition prevents glucan polymer synthesis, disrupting cell wall integrity"]','A','Echinocandins are fungicidal against Candida and fungistatic against Aspergillus. They have minimal human toxicity because mammals lack glucan-containing cell walls.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','medium','flashcard','How is the Cryptococcus neoformans capsule visualised in CSF and what does it look like?','["India ink stain: capsule appears as a clear/unstained halo (negative stain) surrounding a budding yeast cell against a dark background"]','A','Cryptococcal antigen (CrAg) latex agglutination test is more sensitive. Cryptococcus causes meningoencephalitis in HIV patients (CD4 <100).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','medium','flashcard','What is the mechanism of action of amphotericin B?','["Binds ergosterol in fungal cell membrane → forms pores → membrane depolarisation and increased permeability → leakage of intracellular contents → fungal cell death"]','A','Amphotericin B is fungicidal and broad-spectrum but nephrotoxic (infusion-related reactions, renal tubular acidosis). Liposomal formulations reduce nephrotoxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','medium','flashcard','What enzyme do azole antifungals inhibit and what is the result?','["Cytochrome P450 enzyme 14α-demethylase (CYP51); inhibition blocks conversion of lanosterol to ergosterol → depletion of ergosterol and accumulation of toxic methylated sterols"]','A','Azoles (fluconazole, itraconazole, voriconazole, posaconazole) are primarily fungistatic. Drug interactions are common because of CYP450 inhibition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','medium','flashcard','What is the geographic distribution of Histoplasma capsulatum and Blastomyces dermatitidis?','["Both are endemic to the Mississippi and Ohio River Valleys of the USA; Histoplasma is also common in Central/South America; Blastomyces is also found in Great Lakes region"]','A','Histoplasma is associated with bat/bird droppings (spelunking, cleaning chicken coops). Blastomyces is associated with disturbed soil in forested areas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','medium','flashcard','Where is Coccidioides immitis endemic?','["Southwestern USA (California, Arizona, New Mexico, Texas) and parts of Central/South America — the ''desert Southwest''"]','A','Coccidioidomycosis (''Valley Fever'') is acquired by inhaling arthroconidia from dust. In tissue, it forms pathognomonic spherules with endospores.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','hard','flashcard','How does flucytosine (5-FC) exert its antifungal effect?','["5-FC is taken up by fungal cytosine permease and converted by cytosine deaminase to 5-fluorouracil (5-FU) → 5-FU inhibits thymidylate synthase → disrupts fungal DNA and RNA synthesis"]','A','Used in combination with amphotericin B for cryptococcal meningitis. Human cells lack cytosine deaminase, providing selectivity. Resistance develops rapidly if used alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Fungal Biology & Pathogenesis','hard','flashcard','Where is beta-glucan located in the fungal cell and what is its structural role?','["Beta-(1,3)-glucan is a major structural polysaccharide in the fungal cell WALL (outside the cell membrane); it provides rigidity and shape"]','A','Beta-glucan is absent in human cells. Serum (1→3)-β-D-glucan assay is used as a biomarker for invasive fungal infections (not specific for a single species).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','easy','flashcard','Which mosquito genus transmits Plasmodium (malaria) and what is unique about how it feeds?','["Anopheles mosquito; only the female feeds on blood (for egg development), and it bites at dusk/night"]','A','Control measures target the Anopheles vector: insecticide-treated bed nets, indoor residual spraying, larvicide. Aedes mosquitoes transmit Dengue, Zika, Yellow Fever.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','easy','flashcard','What is the fever periodicity of Plasmodium vivax and P. ovale malaria, and why?','["Tertian fever — paroxysms every 48 hours, corresponding to synchronised red blood cell rupture and merozoite release"]','A','P. vivax and P. ovale preferentially infect reticulocytes. Both form hypnozoites in the liver, causing relapses months to years after initial infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','easy','flashcard','What type of fever does Plasmodium malariae cause and at what interval?','["Quartan fever — paroxysms every 72 hours due to a 72-hour erythrocytic cycle"]','A','P. malariae infects older RBCs. It can persist as a low-level chronic parasitaemia for decades and is associated with nephrotic syndrome.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','medium','flashcard','Which Plasmodium species form hypnozoites and what is the clinical significance?','["P. vivax and P. ovale form dormant liver-stage hypnozoites → risk of relapse weeks to years after primary infection and after leaving endemic areas"]','A','Primaquine (and tafenoquine) are required to eradicate hypnozoites (''radical cure''). G6PD deficiency must be checked before use as primaquine causes haemolytic anaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','medium','flashcard','Why is Plasmodium falciparum the most dangerous species of malaria?','["P. falciparum infects RBCs of ALL ages, causing high parasitaemia; infected RBCs express PfEMP1 → cytoadherence to capillary endothelium → microvascular obstruction → cerebral malaria, ARDS, renal failure"]','A','P. falciparum lacks dormant liver stage so does not relapse, but can cause overwhelming acute disease. Sickle cell trait (HbAS) provides partial protection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','medium','flashcard','What is the intermediate host of Schistosoma species and what is the mode of human infection?','["Freshwater snail (genus Bulinus or Biomphalaria); cercariae released from snails penetrate human skin during wading/swimming in contaminated water"]','A','Schistosoma mansoni → hepatic/intestinal disease; S. haematobium → bladder (haematuria, squamous cell carcinoma risk); S. japonicum → intestinal/hepatic. No direct human-to-human transmission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','medium','flashcard','What organism causes river blindness (onchocerciasis) and which vector transmits it?','["Onchocerca volvulus (filarial nematode); transmitted by blackfly (Simulium species) that breeds in fast-flowing rivers"]','A','Microfilariae migrate to eyes → inflammatory reaction → ''river blindness''. Treatment: ivermectin (kills microfilariae). Doxycycline targets endosymbiotic Wolbachia bacteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','medium','flashcard','How does Wuchereria bancrofti cause elephantiasis?','["Adult worms reside in lymphatic vessels → inflammatory obstruction of lymphatic drainage → chronic lymphoedema → massive swelling of legs/scrotum (elephantiasis)"]','A','Transmitted by Culex mosquito. Microfilariae show nocturnal periodicity. Treatment: diethylcarbamazine (DEC) + albendazole; ivermectin in areas co-endemic with Loa loa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','hard','flashcard','What are the characteristics of Giardia lamblia diarrhoea?','["Fatty, greasy, foul-smelling, non-bloody stool (steatorrhoea); no RBCs or WBCs on stool microscopy; upper small bowel infection impairing fat absorption"]','A','Giardia cysts (infective stage) are found in contaminated water (resistant to chlorination). Diagnosis: stool antigen test or O&P for cysts/trophozoites. Treatment: metronidazole.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Parasitology','hard','flashcard','What CNS lesion is caused by Toxoplasma gondii reactivation in HIV patients and how is it identified on imaging?','["Multiple ring-enhancing brain lesions on contrast CT/MRI, typically in the basal ganglia; caused by reactivation of latent Toxoplasma cysts when CD4 count falls below 100 cells/μL"]','A','Empirical treatment with pyrimethamine + sulfadiazine + leucovorin is initiated; clinical/radiological improvement at 2 weeks confirms diagnosis over CNS lymphoma (single lesion, EBV+).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','easy','flashcard','What is the ligand for Toll-like receptor 4 (TLR4) and what is the clinical consequence of TLR4 activation?','["LPS (lipopolysaccharide/endotoxin) from Gram-negative bacteria; TLR4 activation triggers NF-κB → TNF-α, IL-1, IL-6 release → fever, vasodilation, septic shock"]','A','TLR4 signalling via MyD88 adaptor protein. Excessive TLR4 activation is the pathophysiological basis of Gram-negative septic shock.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','easy','flashcard','What is the function of complement component C3b?','["C3b is an opsonin — it coats pathogens and binds CR1 receptors on phagocytes, enhancing phagocytosis"]','A','C3b also initiates the alternative complement pathway amplification loop and contributes to MAC formation (via C5 convertase). C3 deficiency leads to recurrent encapsulated bacterial infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','easy','flashcard','What is the function of C5a in the complement system?','["C5a is an anaphylatoxin and potent chemoattractant — it recruits neutrophils and monocytes to sites of infection and activates mast cells"]','A','C5a also increases vascular permeability and enhances phagocyte oxidative burst. C3a is a weaker anaphylatoxin with similar but less potent effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','medium','flashcard','What is the membrane attack complex (MAC) and how does it kill bacteria?','["MAC = C5b + C6 + C7 + C8 + poly-C9; forms a pore in the bacterial outer membrane → osmotic lysis of Gram-negative bacteria"]','A','Patients with terminal complement deficiency (C5–C9) are susceptible to recurrent Neisseria infections (N. meningitidis, N. gonorrhoeae). MAC does not work well against Gram-positive bacteria (thick PG layer).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','medium','flashcard','What are the key killing mechanisms used by neutrophils after phagocytosis of bacteria?','["Oxidative: NADPH oxidase generates superoxide → H₂O₂ → HOCl (myeloperoxidase); Non-oxidative: defensins, lysozyme, elastase, lactoferrin in granules"]','A','Chronic granulomatous disease (CGD) = NADPH oxidase defect → impaired H₂O₂ production → susceptibility to catalase-positive organisms (Staph aureus, Aspergillus).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','medium','flashcard','What is the target of lysozyme and which organisms are resistant to it?','["Lysozyme cleaves the β-1,4 glycosidic bond between NAM and NAG in peptidoglycan, lysing bacterial cell walls"]','A','Gram-positive bacteria are more susceptible (thicker exposed PG layer). Gram-negative bacteria are partially protected by their outer membrane. Found in saliva, tears, nasal secretions.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','medium','flashcard','How do facultative intracellular organisms survive inside macrophages?','["Various mechanisms: prevent phagolysosome fusion (M. tuberculosis, Legionella); survive in phagolysosome acidic environment (Leishmania); escape phagosome into cytoplasm (Listeria via listeriolysin O)"]','A','Cell-mediated immunity (Th1 → IFN-γ → macrophage activation) is essential to control intracellular organisms. Steroids impair this axis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','hard','flashcard','What is the role of TNF-α in septic shock?','["TNF-α (released by macrophages in response to LPS) causes vasodilation, increased vascular permeability, endothelial activation, DIC, and multi-organ failure — the cardinal features of septic shock"]','A','TNF-α acts synergistically with IL-1 and IL-6. Anti-TNF biologics (infliximab, etanercept) increase susceptibility to TB reactivation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','hard','flashcard','What is the role of the spleen in defence against encapsulated bacteria?','["The spleen filters blood-borne encapsulated bacteria and is the primary site for IgM production against novel polysaccharide antigens; asplenic patients are at risk of overwhelming post-splenectomy infection (OPSI)"]','A','OPSI organisms: S. pneumoniae, H. influenzae, N. meningitidis (''SHiN''). Prophylactic vaccines (pneumococcal, Hib, meningococcal) and penicillin prophylaxis are mandated post-splenectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Host Defence & Innate Immunity','hard','flashcard','What is the Fc receptor and how does it contribute to host defence?','["Fc receptors (FcγR) on phagocytes, NK cells, and mast cells bind the Fc region of IgG on opsonised pathogens → phagocytosis, ADCC (NK cells), or degranulation (mast cells)"]','A','FcγRIII (CD16) on NK cells mediates ADCC — killing of antibody-coated target cells without MHC recognition. Defective Fc receptor function impairs bacterial clearance.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','easy','flashcard','What is the role of CD4+ T-helper cells in the immune response to infection?','["CD4+ Th cells activate B cells (→ antibody production), activate macrophages (Th1/IFN-γ → intracellular killing), and coordinate the overall adaptive immune response"]','A','Th1 cells (IFN-γ) → cell-mediated immunity for intracellular pathogens; Th2 cells (IL-4, IL-5) → humoral immunity for extracellular pathogens/parasites. HIV destroys CD4+ cells, collapsing both arms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','easy','flashcard','Which arm of adaptive immunity (humoral vs cell-mediated) is primarily responsible for defence against extracellular pathogens?','["Humoral immunity — B cells produce antibodies that neutralise extracellular bacteria, viruses, and toxins"]','A','Humoral immunity defects (e.g., X-linked agammaglobulinaemia, CVID) lead to recurrent infections with extracellular encapsulated bacteria. Antibodies cannot reach intracellular pathogens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','easy','flashcard','Which arm of adaptive immunity is critical for controlling intracellular pathogens and cancer?','["Cell-mediated immunity — CD8+ cytotoxic T lymphocytes (CTLs) kill infected cells; CD4+ Th1 cells activate macrophages to destroy intracellular organisms"]','A','CMI defects (AIDS, DiGeorge syndrome, immunosuppressive drugs) predispose to intracellular bacteria (Mycobacteria, Listeria), viruses (CMV, VZV), and fungi (Cryptococcus, PCP).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','medium','flashcard','What is the key advantage of live-attenuated vaccines over killed/inactivated vaccines?','["Live-attenuated vaccines replicate in the host (but do not cause disease) → stimulate strong cell-mediated immunity (CTLs) and humoral immunity, often conferring lifelong immunity with 1–2 doses"]','A','Killed vaccines mainly generate humoral immunity and often require boosters. Live vaccines are contraindicated in immunocompromised patients and pregnancy (risk of disease).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','medium','flashcard','What is a toxoid vaccine and give two examples?','["A toxoid is an inactivated (formalin-treated) bacterial exotoxin that retains antigenicity but loses toxicity; used to generate neutralising antibody against the toxin"]','A','Examples: Diphtheria toxoid (DT) and Tetanus toxoid (TT), combined in DTaP/Tdap. Toxoid vaccines confer immunity to toxin-mediated disease, not bacterial colonisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','medium','flashcard','Why are conjugate vaccines used for encapsulated organisms, especially in infants?','["Polysaccharide antigens alone are T-independent antigens — they do not stimulate memory B cells in children < 2 years; conjugating to a protein carrier converts them to T-dependent antigens, generating IgG and immunological memory"]','A','Examples: Hib (H. influenzae type b), PCV13 (pneumococcal), MenACWY (meningococcal) conjugate vaccines. The protein carrier is usually diphtheria or tetanus toxoid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','medium','flashcard','Where does VZV establish latency and what reactivation disease does it cause?','["VZV is latent in dorsal root ganglia (and cranial nerve ganglia); reactivation causes herpes zoster (shingles) — dermatomal vesicular rash with pain"]','A','Zoster ophthalmicus (V1 branch of CN V) can cause corneal scarring. Post-herpetic neuralgia is the most common complication. Shingrix (recombinant subunit) vaccine reduces incidence by >90%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','hard','flashcard','At what CD4+ T-cell count is AIDS defined and what is the significance?','["AIDS is defined as CD4+ count < 200 cells/μL (or < 14%) OR the presence of an AIDS-defining illness, regardless of CD4 count"]','A','Normal CD4 count is 500–1200 cells/μL. Below 200: PCP, Toxoplasma, Cryptococcus; below 100: CMV retinitis, MAC; below 50: disseminated CMV and MAC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','hard','flashcard','What is the nature of the B-cell response in HIV/AIDS and why is it paradoxical?','["Polyclonal B-cell activation — HIV stimulates non-specific B-cell proliferation via gp41, causing hypergammaglobulinaemia, yet patients are functionally hypo-responsive to new antigens (poor specific antibody formation)"]','A','Result: high total immunoglobulin levels but impaired specific vaccine responses. Patients are susceptible to encapsulated bacteria despite high antibody levels.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Adaptive Immunity & Vaccines','hard','flashcard','How do IgM and IgG antibody levels distinguish acute from past infection?','["IgM = acute/primary infection (rises first, short-lived, indicates current/recent infection); IgG = past infection or vaccination (rises later, long-lived, indicates prior exposure or immunity)"]','A','Exception: IgM can persist >6 months in some infections (e.g., EBV). IgG avidity testing helps: low-avidity IgG = recent infection; high-avidity IgG = past infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','easy','flashcard','What is the mechanism of action of beta-lactamase enzymes?','["Beta-lactamase hydrolyses (cleaves) the beta-lactam ring of penicillins and cephalosporins, inactivating the antibiotic before it can bind PBPs"]','A','Extended-spectrum beta-lactamases (ESBLs) also inactivate 3rd/4th-generation cephalosporins. Beta-lactamase inhibitors (clavulanate, tazobactam, sulbactam) irreversibly bind and inactivate beta-lactamases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','easy','flashcard','What gene confers methicillin resistance in MRSA and what protein does it encode?','["mecA gene encodes PBP2a (PBP2''), a modified penicillin-binding protein with low affinity for all beta-lactam antibiotics"]','A','mecA is carried on the SCCmec mobile genetic element. PBP2a can cross-link peptidoglycan even in the presence of beta-lactams. Treatment: vancomycin, linezolid, daptomycin, or ceftaroline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','easy','flashcard','What is the mechanism of vancomycin resistance in VRE?','["Van gene clusters (vanA/vanB) encode enzymes that substitute D-Ala-D-Ala terminus of peptidoglycan precursors with D-Ala-D-Lac → vancomycin cannot bind → no inhibition of cell wall synthesis"]','A','D-Ala-D-Ala is the normal vancomycin binding site. D-Lac substitution reduces vancomycin binding affinity 1000-fold. VanA confers high-level resistance to vancomycin AND teicoplanin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','medium','flashcard','Which organisms are the classic producers of ESBLs and in what clinical settings are they important?','["Klebsiella pneumoniae and E. coli are the most common ESBL producers; important in hospital-acquired and community UTIs, bacteraemia, and pneumonia — especially in patients with prior antibiotic exposure"]','A','ESBLs hydrolyse penicillins AND 3rd-generation cephalosporins. Detection: double-disk synergy test. Treatment: carbapenems (imipenem, meropenem, ertapenem).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','medium','flashcard','What is the treatment of choice for ESBL-producing Gram-negative infections?','["Carbapenems (imipenem, meropenem, ertapenem) are the drugs of choice for serious ESBL infections"]','A','For uncomplicated ESBL UTIs, nitrofurantoin or fosfomycin may be used if susceptible. Cephalosporins should NOT be used even if in vitro susceptibility is reported (inoculum effect).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','medium','flashcard','What is the primary resistance mechanism to tetracyclines and which organisms commonly employ it?','["Efflux pumps actively export tetracycline from the bacterial cytoplasm before it can inhibit the 30S ribosome; encoded by tet genes on plasmids"]','A','Ribosomal protection proteins (e.g., TetM) are a secondary mechanism. Minocycline and tigecycline are poor efflux pump substrates and retain activity against some resistant strains.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','medium','flashcard','What are KPC and NDM-1 and why are they clinically alarming?','["KPC (Klebsiella pneumoniae carbapenemase) and NDM-1 (New Delhi metallo-beta-lactamase) are carbapenemases — enzymes that hydrolyse and inactivate carbapenem antibiotics, the ''last-resort'' beta-lactams"]','A','Carbapenemase genes are often on plasmids, enabling rapid horizontal spread. CRE (carbapenem-resistant Enterobacteriaceae) carrying KPC or NDM-1 are pan-resistant to most antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','hard','flashcard','What agents are used as last-resort treatment for carbapenem-resistant Enterobacteriaceae (CRE)?','["Tigecycline (glycylcycline, inhibits 30S), colistin/polymyxin B (disrupts outer membrane), and newer agents: ceftazidime-avibactam, meropenem-vaborbactam, imipenem-relebactam"]','A','Colistin causes nephrotoxicity and neurotoxicity. Combination therapy (e.g., colistin + carbapenem + tigecycline) is often used for serious CRE infections. Susceptibility testing is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','hard','flashcard','How does plasmid-mediated transfer of resistance genes differ from chromosomal mutation in terms of speed of resistance spread?','["Plasmids can transfer resistance genes horizontally between different bacterial species and genera within hours (conjugation), conferring immediate resistance — far faster than chromosomal point mutations"]','A','Resistance plasmids (R plasmids) often carry multiple resistance genes simultaneously, creating multidrug-resistant organisms in a single transfer event. This is why antibiotic stewardship is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Antimicrobial Resistance Mechanisms','hard','flashcard','What resistance mechanism makes Pseudomonas aeruginosa intrinsically resistant to many antibiotics?','["Loss/downregulation of outer membrane porins (OprD and others) reduces drug entry into the cell, combined with constitutive expression of efflux pumps (MexAB-OprM) and production of chromosomal AmpC beta-lactamase"]','A','This multi-mechanism intrinsic resistance means Pseudomonas is treated only with anti-pseudomonal beta-lactams (piperacillin-tazobactam, cefepime, carbapenems), fluoroquinolones, or aminoglycosides — often in combination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','easy','flashcard','What Gram-stain morphology and arrangement suggests Staphylococcus species?','["Gram-positive cocci in clusters (''bunches of grapes'')"]','A','Staph aureus is catalase-positive and coagulase-positive; S. epidermidis is coagulase-negative. Distinguishing coagulase-positive from -negative is clinically critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','easy','flashcard','What Gram-stain morphology suggests Streptococcus species?','["Gram-positive cocci in chains or pairs"]','A','S. pyogenes (Group A Strep) forms long chains; S. pneumoniae appears as lancet-shaped diplococci. Further differentiation uses haemolysis pattern on blood agar (alpha/beta/gamma).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','easy','flashcard','Which organism appears as Gram-negative diplococci and what infections does it cause?','["Neisseria species — N. meningitidis (meningitis, septicaemia) and N. gonorrhoeae (gonorrhoea, PID, neonatal ophthalmia)"]','A','On smear of urethral/cervical discharge, intracellular Gram-negative diplococci within PMNs are virtually diagnostic of gonorrhoea. Require CO₂ and chocolate agar for culture.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','medium','flashcard','What stain is used to identify acid-fast organisms and what do they look like?','["Ziehl-Neelsen (ZN) stain (or auramine-O fluorescent stain); acid-fast bacilli appear as bright red/pink rods against a blue background (ZN) or fluorescent yellow-green (auramine)"]','A','Acid-fast organisms: Mycobacterium tuberculosis, M. avium complex, M. leprae, and Nocardia (partially acid-fast). Standard Gram stain does not stain Mycobacteria reliably.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','medium','flashcard','What selective medium is used to culture Neisseria gonorrhoeae and why is it selective?','["Thayer-Martin medium (modified chocolate agar + vancomycin + colistin + nystatin + trimethoprim); antibiotics suppress normal flora while allowing Neisseria to grow"]','A','N. gonorrhoeae requires cysteine and is CO₂-dependent. Thayer-Martin is used for genital, rectal, and pharyngeal swabs. Chocolate agar is used for sterile site specimens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','medium','flashcard','What is Sabouraud dextrose agar and what is its use in microbiology?','["Sabouraud agar is a selective medium with low pH (~5.6) and high dextrose that inhibits bacteria and promotes fungal growth; incubated at 25–30°C for mould identification"]','A','Used to culture dermatophytes, Candida, dimorphic fungi, and other pathogenic fungi. Dermatophytes grow as powdery/fluffy colonies over 1–2 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','medium','flashcard','What is the correct sequence of HIV diagnostic testing?','["1st: HIV-1/2 antigen-antibody combination immunoassay (4th-generation ELISA detecting p24 antigen + antibody); if reactive → 2nd: HIV-1/HIV-2 antibody differentiation assay; if discordant → HIV RNA NAAT (PCR)"]','A','Old paradigm: ELISA → Western blot confirmatory. Current CDC algorithm uses the 4th-generation combo assay as first test. Detects HIV earlier (p24 antigen appears 2 weeks after infection).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','medium','flashcard','How do IgM and IgG serology results distinguish acute from past infection in clinical microbiology?','["IgM positive = acute/primary infection (first antibody produced, peaks at 1–2 weeks, wanes over months); IgG positive alone = past infection or vaccination (long-lived, can persist lifelong)"]','A','Both IgM and IgG positive together suggests recent/acute infection still evolving. IgG avidity assays (low avidity = recent, high avidity = remote) add precision for Toxoplasma and CMV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','hard','flashcard','What is the key clinical advantage of PCR/NAAT over culture in diagnosing infectious diseases?','["PCR/NAAT can detect organisms that are non-culturable, slow-growing, or present in small quantities; provides rapid results (hours vs days-weeks for culture) and can work on dead organisms and non-sterile specimens"]','A','Examples: detecting M. tuberculosis in sputum within hours (GeneXpert MTB/RIF), detecting STIs (Chlamydia, Gonorrhoea) on non-invasive urine/swabs, diagnosing viral infections (HSV, CMV, HIV viral load).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Laboratory Diagnosis','hard','flashcard','What stain is used to visualise Cryptococcus neoformans in CSF and what is the pathognomonic finding?','["India ink stain: Cryptococcus appears as budding yeast with a wide unstained capsular halo against a dark background — ''halo sign''"]','A','Cryptococcal antigen (CrAg) latex agglutination in CSF is more sensitive (>95%) and specific than India ink. Opening pressure on LP is typically elevated (>25 cmH₂O) in cryptococcal meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','easy','flashcard','What are the standard autoclave conditions for sterilisation?','["121°C at 15 psi (103 kPa) for 15–20 minutes; high-temperature steam under pressure"]','A','Autoclaving is the gold standard for sterilising heat-stable medical instruments and laboratory equipment. It kills all microorganisms including endospores.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','easy','flashcard','Why is autoclaving necessary rather than simple boiling to sterilise instruments?','["Boiling (100°C at 1 atm) does not kill bacterial endospores (e.g., Clostridium, Bacillus); autoclave pressure steam (121°C) provides enough heat energy to denature spore proteins"]','A','Endospores are the most resistant form of life — they survive boiling for hours. Moist heat (autoclave) is more effective than dry heat because water conducts heat and denatures proteins more efficiently.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','easy','flashcard','What is the difference between disinfection and sterilisation?','["Sterilisation = destruction of ALL microorganisms including spores; Disinfection = reduction of microbial load to safe levels (does not kill all spores) — used on inanimate surfaces, not surgical instruments"]','A','Antiseptics are disinfectants used on living tissue. Critical items (surgical instruments, implants) require sterilisation; semi-critical items (endoscopes) require high-level disinfection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','medium','flashcard','Which organisms require airborne precautions (negative pressure room, N95 respirator) and why?','["TB (Mycobacterium tuberculosis), Measles (Rubeola), Varicella-Zoster (Chickenpox) — mnemonic ''MTV''; these produce small droplet nuclei (<5 μm) that remain suspended in air for hours and travel >1 metre"]','A','Negative pressure rooms prevent air from escaping to corridors. N95 respirators filter particles ≥0.3 μm. Standard surgical masks are insufficient for airborne precautions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','medium','flashcard','Which organisms require droplet precautions and what PPE is used?','["Influenza, Neisseria meningitidis, Bordetella pertussis, Mumps, Rubella, adenovirus — large droplets (>5 μm) travel <1 metre; surgical mask + eye protection within 1 metre"]','A','Mnemonic for droplet: ''SPIDERMAN'' — Strep pharyngitis, Pertussis, Influenza, Diphtheria, Epiglottitis, Rubella, Adenovirus, Meningococcus, and Mycoplasma (pneumonia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','medium','flashcard','Which organisms require contact precautions and what PPE is used?','["MRSA, VRE, C. difficile, multi-drug-resistant Gram-negative rods, RSV, norovirus, rotavirus — gloves + gown on entering room; dedicated equipment"]','A','C. difficile spores are resistant to alcohol-based hand gels — soap and water with physical friction is essential. Contact precautions involve single room or cohorting of patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','medium','flashcard','What is the single most effective measure to prevent healthcare-associated infections?','["Hand hygiene — washing with soap and water or using alcohol-based hand rub (ABHR) before and after patient contact"]','A','WHO 5 moments for hand hygiene: before patient contact, before aseptic procedure, after body fluid exposure, after patient contact, after contact with patient surroundings. ABHR kills most organisms except C. difficile spores.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','medium','flashcard','What is the most common cause of nosocomial (hospital-acquired) urinary tract infection?','["Urinary catheterisation (CAUTI — catheter-associated UTI); biofilm forms on catheter surface within 24–48 hours; E. coli, Klebsiella, Candida, Pseudomonas, Enterococcus are common pathogens"]','A','Risk reduction: use urinary catheters only when necessary, use aseptic insertion technique, remove catheter as early as possible. CAUTIs account for ~40% of all hospital-acquired infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','hard','flashcard','What makes the NAP1 strain of C. difficile particularly virulent?','["NAP1/BI/027 strain produces binary toxin (in addition to toxins A and B), has a deletion in the tcdC regulatory gene allowing toxin overproduction, and is hypervirulent with higher rates of severe disease, relapse, and mortality"]','A','NAP1 is the strain responsible for major hospital outbreaks. C. difficile spores are resistant to standard cleaning — bleach-based disinfectants and soap-and-water hand hygiene are essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Anatomy & Physiology','Infection Control & Epidemiology','hard','flashcard','Why is the Anopheles mosquito the only vector capable of transmitting malaria and how does this inform control strategies?','["Only Anopheles mosquitoes support development of Plasmodium through the sporogonic cycle (oocyst → sporozoites in salivary glands); control strategies target Anopheles specifically: insecticide-treated bed nets, indoor residual spraying with pyrethroids, larval source management, and sterile insect technique"]','A','Anopheles bites at dusk and night, feeds with body at an angle (distinguishes from Aedes which bites during the day). Insecticide resistance in Anopheles is a growing global concern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
